(function(){
'use strict';
const D=ATLAS,U=AtlasDomain,$=s=>document.querySelector(s),E=U.esc;
const state={city:'taipei',tab:'candidates',year:2022,person:null,region:'cn'};
const parties={KMT:'中国国民党',DPP:'民主进步党'},labels={cn:'两岸 / 中国大陆',us:'美国',jp:'日本'},dialog=$('#dossier');
const partyClass=p=>p==='KMT'?'kmt':p==='DPP'?'dpp':'';
const badge=p=>`<span class="party ${partyClass(p)}">${E(parties[p]||p)}</span>`;
const num=n=>new Intl.NumberFormat('zh-CN').format(n);
function src(id,label){return AtlasMedia.render(id,label);}
function city(){return D.cities.find(c=>c.id===state.city);}
function selectCity(id){if(D.cities.some(c=>c.id===id))location.hash='/'+id;}
function renderCities(){
 const choices=AtlasCountyGuide.options(state.city);
 for(const selector of ['#city-switch','#history-cities']) $(selector).innerHTML='<label class="county-chooser">县市 <select data-county-select>'+choices+'</select></label>';
}
function renderCity(){
 const c=city(),n=D.counties[c.id].ballot.length;
 document.title=c.fullName+' · 岛屿选战';
 renderCities(); AtlasMap.select(c.id); $('.edition b').textContent=c.index+' / '+D.cities.length;
 const districts=c.id==='taipei'?'<a class="district-guide-link" href="taipei.html"><span>台北十二区导览</span><span>↗</span></a>':'';
 $('#city-heading').innerHTML='<div class="city-title"><div><h2>'+E(c.fullName)+'</h2><div class="en">'+E(c.en)+'</div></div><div class="city-count"><strong>'+n+'</strong><span>首长候选人</span></div></div><p class="city-caption">'+E(c.caption)+'</p><a class="district-guide-link" href="#/'+c.id+'/overview"><span><b>县市档案与两地对照</b><small>人口、所得、产业、地方议题与代表</small></span><span aria-hidden="true">↓</span></a>'+districts;
 AtlasCountyGuide.render(c.id);renderPanel();renderHistory();window.AtlasResearch?.renderCity(c.id);AtlasPolicies.render(c.id);
}
function normalize(v){const a='蔣萬蘇輝湟蕭啟陳賴龍燐麗謝郭張葉柯純靜豐縣臺',b='蒋万苏辉湟萧启陈赖龙燐丽谢郭张叶柯纯静丰县台';return v.toLowerCase().replace(/[蔣萬蘇輝湟蕭啟陳賴龍燐麗謝郭張葉柯純靜豐縣臺]/g,c=>b[a.indexOf(c)]);}
function renderCandidates(query=''){const list=D.people.filter(p=>p.city===state.city&&normalize(p.name+' '+(p.searchName||'')+' '+p.bio+' '+(parties[p.party]||p.party)).includes(normalize(query)));$('#candidate-list').innerHTML=list.length?list.map(p=>`<button class="candidate-row" data-person="${p.id}" aria-label="查看${E(p.name)}档案">${AtlasProfiles.portrait(p)}<span class="candidate-main"><span class="candidate-name"><small>${p.ballotNumber}号</small> ${E(p.name)}</span>${badge(p.party)}<span class="candidate-role" style="display:block">${E(p.bio)}</span></span><span class="row-arrow" aria-hidden="true">↗</span></button>`).join(''):'<div class="no-results">本市没有匹配的已收录参选人。请尝试姓名或党籍。</div>';}
function results(e,mini=false){const allPercent=e.rows.every(r=>U.percent(r,e)!==null),max=Math.max(...e.rows.map(r=>r[2]));return `<div class="${mini?'mini-results':''}">${e.rows.map(r=>{const p=U.percent(r,e),width=allPercent?p:r[2]/max*100;return `<div class="result-row"><div class="result-label"><span>${E(r[0])}${badge(r[1])}</span><b>${num(r[2])}<small>${p===null?'票':p.toFixed(2)+'%'}</small></b></div><div class="bar-track" aria-hidden="true"><div class="bar-fill ${partyClass(r[1])}" style="width:${width.toFixed(4)}%"></div></div></div>`;}).join('')}<p class="results-note">${E(e.scope)}。${allPercent?'百分比为当届得票率，完整记录按有效票合计计算。':'条长以本组最高票数归一化，不是得票率。'}<br>实际选举结果，不代表2026年支持率。</p><div class="source-line">${e.sources.map(s=>src(s)).join('')}</div></div>`;}
function renderPanel(){document.querySelectorAll('[data-tab]').forEach(b=>{const on=b.dataset.tab===state.tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;});$('#panel-content').setAttribute('aria-labelledby','tab-'+state.tab);
if(state.tab==='candidates'){$('#panel-content').innerHTML='<label class="candidate-search"><input id="candidate-search" type="search" aria-label="查找本市参选人" placeholder="查找本市参选人或党籍…" autocomplete="off"></label><a class="outline-button" href="#policies">按议题对比政见 ↓</a><div id="candidate-list"></div><div class="source-line">'+AtlasMedia.refs([D.counties[state.city].registerSource,'county-approval','county-ballot','county-bio'])+'</div>';renderCandidates();$('#candidate-search').addEventListener('input',e=>renderCandidates(e.target.value));}
else if(state.tab==='polls'){$('#panel-content').innerHTML=AtlasMap.polls(state.city)+`<div class="note">以下是2022年的实际选票，不是本届调查。</div><h3 style="font-weight:400;font-size:16px;margin:23px 0">2022 · ${city().fullName}首长选举</h3>${results(D.elections.find(e=>e.city===state.city&&e.year===2022),true)}`;}
else {const c=D.counties[state.city];$('#panel-content').innerHTML='<div class="empty-state"><h3>'+E(c.name)+'的生活与选举</h3><p>'+E(c.place)+'</p>'+(city().history!==c.place?'<p>'+E(city().history)+'</p>':'')+'<div class="source-line">'+AtlasMedia.refs(['county-place-'+c.id,'local51','merger'])+'</div><a class="outline-button" href="#/'+c.id+'/overview">查看地方档案与两地对照 ↓</a><a class="outline-button" href="#history">查看历届首长得票 ↓</a></div>';}}
function renderHistory(){
 if(state.city==='taipei') AtlasResearch.renderHistory(state.year,results,src);
 else AtlasCountyGuide.history(state.city,state.year,results);
}
function openPerson(id){const p=D.people.find(p=>p.id===id);if(!p)return;state.person=id;state.region='cn';document.title=p.name+' · 人物档案 · 岛屿选战';const c=city();$('#dialog-content').innerHTML=`<div class="profile-hero">${AtlasProfiles.portrait(p,'hero')}<div><div class="eyebrow">${c.en} / 2026</div><h2 id="dialog-title">${E(p.name)}</h2>${badge(p.party)}<p>${p.ballotNumber} 号 · 登记 ${E(p.registration)}</p></div></div><p class="profile-intro">${E(p.bio)}</p><p class="muted" style="font-size:10px">${E(p.status)}。经历按来源发布时点记录。</p><div class="profile-actions">${src(p.source,'身份与经历来源')}<button class="outline-button" id="copy-link">复制档案链接 ↗</button></div>${AtlasProfiles.photoCredit(p)}${p.countyBrief?AtlasCountyGuide.brief(p):''}${AtlasPolicies.profile(p)}<section class="profile-section"><h3>向外看：三份言行记录</h3><p>按议题查看有日期的表态与行动，不提供“亲谁”分数。资料覆盖范围因人而异；每条记录均注明日期与来源，不用于人物评分。</p><div class="region-tabs" role="group" aria-label="选择对外关系方向">${Object.entries(labels).map(([k,v])=>`<button data-region="${k}" aria-pressed="${k==='cn'}">${v}</button>`).join('')}</div><div id="evidence-content"></div></section><section class="profile-section"><h3>争议与核查</h3><p>数量反映本版的收录进度，不代表人物的争议程度或清白证明。</p>${p.controversies.length?p.controversies.map(v=>`<article class="evidence-card"><span class="state">${E(v.status)}</span><time>${v.date}</time><h4>${E(v.title)}</h4><div class="event-line"><span>${E(v.claimLabel||'请求 / 指控')}</span><p>${E(v.claim)}</p></div><div class="event-line"><span>已知结论</span><p>${E(v.outcome)}</p></div><div class="event-line"><span>本人回应</span><p>${E(v.reply)}</p></div><p class="limit">${E(v.limit)}</p>${(v.sources||[v.source]).map(id=>src(id)).join('')}</article>`).join(''):'<div class="empty-state"><h3>暂未收录完成核查的事件。</h3><p>需要原始依据、回应和后续进展。未收录不代表没有争议，不能据此与其他人物比较。</p></div>'}</section><section class="profile-section"><p>已建档照片随网站保存；出处、图像年代与许可或引用说明见档案上方。<button class="text-button source-open">查看资料标准 ↗</button></p></section>`;renderEvidence();window.AtlasResearch?.renderPerson(p);if(!dialog.open)dialog.showModal();}
function renderEvidence(){const p=D.people.find(p=>p.id===state.person);if(!p)return;const records=p.evidence.filter(e=>e.region===state.region),review=p.evidenceCoverage?.[state.region];document.querySelectorAll('[data-region]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.region===state.region));$('#evidence-content').innerHTML=records.length?records.map(v=>`<article class="evidence-card"><time>${E(v.date)}</time><h4>${E(v.topic)}</h4><p>${E(v.text)}</p><p class="limit">${E(v.limit)}</p>${(v.sources||[v.source]).map(id=>src(id)).join('')}</article>`).join(''):review?`<article class="evidence-card evidence-review"><time>查阅 ${E(review.checkedAt)}</time><h4>暂未确认：已查材料中未找到明确表态</h4><p>${E(review.scope)}</p><p class="limit">${E(review.note)}</p>${AtlasMedia.refs(review.sources)}</article>`:`<div class="empty-state"><h3>尚未查核：这条证据线还没补齐。</h3><p>目前尚未完成对${labels[state.region]}相关公开言行的核查；这不表示没有相关观点。不会从党籍、留学经历或合影自动推断立场。</p></div>`;}
function applyRoute(){
 const hash=location.hash,section=hash&&!hash.startsWith('#/');
 if(section && document.querySelector('#city-heading').children.length)return;
 const r=U.route(section?'':hash,D);
 if(!AtlasCountyGuide.timeline(r.city).includes(state.year))state.year=2022;
 state.city=r.city;state.person=r.person;renderCity();
 if(r.person)openPerson(r.person);else if(dialog.open)dialog.close();
 if(hash.endsWith('/overview')) requestAnimationFrame(()=>$('#county-guide').scrollIntoView());
}
document.addEventListener('change',e=>{if(e.target.matches('[data-county-select]'))selectCity(e.target.value);});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
document.addEventListener('click',async e=>{const cityButton=e.target.closest('[data-select-city]');if(cityButton){selectCity(cityButton.dataset.selectCity);return;}const person=e.target.closest('[data-person]');if(person){location.hash='/'+state.city+'/'+person.dataset.person;return;}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;renderPanel();return;}const year=e.target.closest('[data-year]');if(year){state.year=Number(year.dataset.year);renderHistory();AtlasMap.update(state.year);return;}const region=e.target.closest('[data-region]');if(region){state.region=region.dataset.region;renderEvidence();return;}if(e.target.closest('.source-open')){$('#sources-dialog').showModal();return;}if(e.target.closest('#back-current')){state.tab='candidates';renderPanel();$('#city-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}if(e.target.closest('#copy-link')){try{await navigator.clipboard.writeText(location.href);toast('已复制人物档案链接。');}catch{toast('当前环境无法复制，请从地址栏复制链接。');}}});
$('.panel-tabs').addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('.panel-tabs [data-tab]')],i=tabs.indexOf(document.activeElement);if(i<0)return;let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();state.tab=tabs[next].dataset.tab;renderPanel();tabs[next].focus();});
$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{if(state.person){state.person=null;history.replaceState(null,'','#/'+state.city);document.title=city().name+' · 岛屿选战';}});$('#close-sources').onclick=()=>$('#sources-dialog').close();for(const d of [dialog,$('#sources-dialog')])d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}});
$('#source-list').innerHTML=AtlasMedia.room();
const mergerSource=$('#guide-merger-source');if(mergerSource)mergerSource.innerHTML=AtlasMedia.render('merger','县市改制沿革来源');
setInterval(()=>{AtlasMap.update();if(state.tab==='polls')renderPanel();},60000);
AtlasMap.init(id=>{selectCity(id);if(matchMedia('(max-width:950px)').matches)setTimeout(()=>$('#city-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'}),80);});window.addEventListener('hashchange',applyRoute);applyRoute();
})();
